INSERT INTO content (title, code, description, answer, before_code, after_code, feedback, image_url, question, company, views, bookmarks, is_active, created_at, updated_at, deleted_at, type) VALUES ('💡 배열 마지막 요소 접근', 'const arr = [1, 2, 3, 4, 5]\narr.at(-1) // 5\narr.at(-2) // 4', '## 배열 마지막 요소 접근\n\n배열의 마지막 요소에 접근할 때 `.at(-1)`을 사용하면 더 깔끔합니다.\n\n### 기존 방식\n```javascript\narr[arr.length - 1]\n```\n\n### 개선 방식\n```javascript\narr.at(-1)\n```\n\n### 추가 기능\n- 음수 인덱스로 뒤에서부터 접근 가능\n- `at(-2)`는 뒤에서 두 번째 요소\n\n**ES2022**부터 지원됩니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2477, 255, true, '2025-11-23 23:28:43.745', '2025-11-28 15:20:46.233', NULL, 'CODE_TIP');
INSERT INTO content (title, code, description, answer, before_code, after_code, feedback, image_url, question, company, views, bookmarks, is_active, created_at, updated_at, deleted_at, type) VALUES ('🐛 useState 클로저 트랩', 'const [count, setCount] = useState(0)\n\nsetTimeout(() => {\n  setCount(count + 1)\n}, 1000)\n\nsetTimeout(() => {\n  setCount(count + 1)\n}, 2000)', '## 문제점\n\n`count`가 클로저에 캡처되어 두 setTimeout 모두 `count = 0`을 참조합니다.\n따라서 2초 후 count는 2가 아닌 1이 됩니다.\n\n## 해결 방법\n\n### 함수형 업데이트 사용\n```javascript\nsetTimeout(() => {\n  setCount(prev => prev + 1)\n}, 1000)\n\nsetTimeout(() => {\n  setCount(prev => prev + 1)\n}, 2000)\n```\n\n함수형 업데이트를 사용하면 항상 최신 상태를 참조합니다!\n\n### 왜 발생하나요?\n- 클로저는 함수가 선언될 때의 변수를 캡처\n- `count`는 0으로 고정됨\n- 함수형 업데이트는 React가 최신 값을 제공', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 801, 93, true, '2025-11-23 23:28:43.745', '2025-11-28 15:20:46.260', NULL, 'CODE_TIP');
INSERT INTO content (title, code, description, answer, before_code, after_code, feedback, image_url, question, company, views, bookmarks, is_active, created_at, updated_at, deleted_at, type) VALUES ('👨‍💻 배열 중복 제거 개선', NULL, '## 개선 포인트\n\nSet을 활용하면 간결하고 성능도 좋습니다.\n\n### Before 문제점\n- **O(n²) 시간 복잡도**: `includes()`가 매번 배열 전체를 순회 (O(n))\n- 코드가 길고 복잡함\n- 가독성이 떨어짐\n\n### After 장점\n- ✅ **O(n) 시간 복잡도**: Set은 해시 테이블 기반\n- ✅ **한 줄로 해결**: 간결한 코드\n- ✅ **가독성 향상**: 의도가 명확함\n\n### Set의 특징\n- 중복을 자동으로 제거\n- 순서 보장 (ES2015+)\n- 원시값과 객체 참조 모두 저장 가능', NULL, 'const unique = []\nfor(let i = 0; i < arr.length; i++) {\n  if(!unique.includes(arr[i])) {\n    unique.push(arr[i])\n  }\n}', 'const unique = [...new Set(arr)]', '## 개선 포인트\n\nSet을 활용하면 간결하고 성능도 좋습니다.', NULL, NULL, NULL, 710, 137, true, '2025-11-23 23:28:43.745', '2025-11-28 15:20:46.271', NULL, 'CODE_REVIEW');
INSERT INTO category_content (content_id, category_id) VALUES(1, 14), (1, 21), (1, 29), (2, 1), (2, 10), (2, 28), (3, 11), (3, 21), (3, 31);